<?php $images=json_decode($item['images'],true) ?: []; ?><article class="classified-card"><a class="classified-image" href="<?= e(url('classifieds/'.$item['id'])) ?>"><img src="<?= e(media_url($images[0] ?? null)) ?>" alt="" loading="lazy" width="640" height="400"><?php if ($item['is_premium']): ?><span class="premium-label">Premium</span><?php endif ?></a><div class="classified-copy"><div class="eyebrow"><?= e($item['category_name'] ?? $item['location']) ?></div><h3><a href="<?= e(url('classifieds/'.$item['id'])) ?>"><?= e($item['title']) ?></a></h3><p class="price"><?= $item['price']!==null ? 'LKR '.number_format((float)$item['price'],2) : 'Contact for price' ?></p><div class="meta"><span>⌖ <?= e($item['location']) ?></span><span><?= e(date('d M',strtotime($item['created_at']))) ?></span></div></div></article>
